import{z as l,x as i,o as s,c as n,q as t,j as p,D as r,d as E,s as A,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Paxos","description":"","frontmatter":{"title":"Paxos","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/paxos.md","filePath":"cs/paxos.md","lastUpdated":1791063341000}'),d={name:"cs/paxos.md"};function C(m,a,P,c,x,u){const o=i("Mermaid");return s(),n("div",null,[a[2]||(a[2]=t('<h1 id="paxos" tabindex="-1">Paxos <a class="header-anchor" href="#paxos" aria-label="Permalink to &quot;Paxos&quot;">​</a></h1><div class="epigraph"><p>两阶段：先争一个提案编号的承诺，再对那个编号接受值。多数派相交让两个被选中的值不能不同。活性不保证——FLP 允许。</p><footer>—— 据 Lamport, The Part-Time Parliament, TOCS 1998；Paxos Made Simple, 2001 整理</footer></div><p>上一课<a href="/cs/replicated-state-machine">复制状态机</a>要一条全序日志。缺口是<strong>单槽共识</strong>：多数崩溃停进程如何对「这个 index 写什么」达成一致。本课钉 Basic Paxos，不把 Multi-Paxos 的稳定领导者写完。后课默认：prepare/accept、承诺、多数派这些词已经钉死。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>提议者选编号 \\(n\\)，向接受者发 prepare。若 \\(n\\) 大于该接受者已承诺的编号，则承诺忽略更小者，并返回已接受的最高值。提议者若收到多数派回复：若有人带过值，必须提议其中编号最高的那个；否则可提议自己的值。然后 accept。若多数派接受，该值被选定。</p><p><span class="marginnote">数字实例：5 个接受者时，多数派至少要 3 个。任意两个 3 人小组必至少共享 1 人——比如 {A,B,C} 与 {C,D,E} 共享 C。正是这个交集保证：如果第一个多数派已接受值 v，后一个 prepare 一定会在 C 那里「看见」v，从而被迫跟着提 v，两个不同的值不可能都被选定。</span></p><p>缺口：为何安全。任意两个多数派相交，后一次 prepare 会看见前一次已接受的值并被迫跟着走，于是不能选定第二个不同值。与<a href="/cs/quorum-rw">quorum 寄存器</a>同构在相交，对象是「这个槽的值」而不是客户端 blob。</p><p><span class="marginnote">TOCS 1998 用议会寓言；2001 短文去掉寓言。编号必须全局唯一且单调，常用 <code>(计数, 节点 id)</code>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>角色可重叠：每节点提议者+接受者+学习者。学习者靠 accept 广播或向多数派查询。冲突：两个提议者交错 prepare，可能活锁——这是活性，不是安全洞。编号加一重试。</p><p><span class="marginnote">活锁直觉：两个提议者像在窄门口互相谦让的两个人——你抬编号我让步，我抬编号你让步，谁也进不去，但谁也不会撞上谁（安全没破）。实践解法是随机退避错开时机，或干脆选一个「主提议者」长期独占（Multi-Paxos 的领导者）。</span></p>',11)),(s(),p(B,null,{default:r(()=>[A(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRE%5B%22prepare%20n%22%5D%20--%3E%20PROM%5B%22%E5%A4%9A%E6%95%B0%E6%B4%BE%E6%89%BF%E8%AF%BA%22%5D%0A%20%20PROM%20--%3E%20VAL%5B%22%E9%80%89%E5%80%BC%3A%20%E5%B7%B2%E6%8E%A5%E5%8F%97%E7%9A%84%E6%9C%80%E9%AB%98%20%2F%20%E8%87%AA%E5%A4%87%22%5D%0A%20%20VAL%20--%3E%20ACC%5B%22accept%22%5D%0A%20%20ACC%20--%3E%20CHOSEN%5B%22%E5%A4%9A%E6%95%B0%E6%B4%BE%E6%8E%A5%E5%8F%97%20%E2%87%92%20%E9%80%89%E5%AE%9A%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[E("信道可丢消息、可延迟；崩溃恢复必须把承诺编号与已接受值写进稳定存储，否则"),e("a",{href:"/cs/failure-models"},"崩溃恢复"),E("会改口。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"FLP：纯异步下可能永远活锁或永远选不出。实践加随机退避与「尽量一个提议者」。安全证明不依赖超时。部分同步下超时让某个提议者的 \\(n\\) 跑在前面，于是终止。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"常见误区：以为超时是 Paxos 正确性的一部分。实际上超时只服务「终止」（别永远选不出）；「至多一个值」这条安全性质在任意时序、任意丢消息下都成立——哪怕全网乱序卡死，也不会出现两个多数派各记住一个不同值。")],-1)),(s(),p(B,null,{default:r(()=>[A(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20PA%5B%22%E6%8F%90%E8%AE%AE%E8%80%85%E7%94%B2%EF%BC%9Aprepare%205%22%5D%20--%3E%20Q1%5B%22%E5%A4%9A%E6%95%B0%E6%B4%BE%20A%2CB%2CC%20%E6%89%BF%E8%AF%BA%E5%B9%B6%E6%8E%A5%E5%8F%97%20v%22%5D%0A%20%20PB%5B%22%E6%8F%90%E8%AE%AE%E8%80%85%E4%B9%99%EF%BC%9Aprepare%207%EF%BC%8C%E7%A8%8D%E5%90%8E%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20Q2%5B%22%E5%A4%9A%E6%95%B0%E6%B4%BE%20C%2CD%2CE%20%E6%89%BF%E8%AF%BA%22%5D%0A%20%20Q1%20--%3E%20C1%5B%22C%20%E8%AE%B0%E4%BD%8F%EF%BC%9A%E5%B7%B2%E6%8E%A5%E5%8F%97%20v%22%5D%0A%20%20C1%20--%3E%20I%5B%22%E4%B8%A4%E4%B8%AA%E5%A4%9A%E6%95%B0%E6%B4%BE%E5%9C%A8%20C%20%E7%9B%B8%E4%BA%A4%22%5D%0A%20%20I%20--%3E%20R%5B%22%E4%B9%99%E4%BB%8E%20C%20%E7%9C%8B%E5%88%B0%20v%EF%BC%8C%E8%A2%AB%E8%BF%AB%E6%8F%90%20v%20%E8%80%8C%E9%9D%9E%E8%87%AA%E5%B7%B1%E7%9A%84%E5%80%BC%22%5D%0A%20%20R%20--%3E%20S%5B%22%E4%B8%8D%E5%90%8C%E5%80%BC%E6%97%A0%E6%B3%95%E8%A2%AB%E7%AC%AC%E4%BA%8C%E4%B8%AA%E5%A4%9A%E6%95%B0%E6%B4%BE%E9%80%89%E5%AE%9A%EF%BC%9A%E5%AE%89%E5%85%A8%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<p>单槽只决定一个值。状态机需要槽序列——下一课。不要把 2PC 的协调者当 Paxos：2PC 阻塞在协调者崩溃，Paxos 换提议者。后课专门对照。</p><p>本课不写拜占庭 Paxos。口头撒谎会分裂多数派观察，Lamport 的原版假定非拜占庭。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写磁盘布局、不引入联合多数派（membership）。不把 ZooKeeper 当 Paxos 实现细节。后课默认：一个值的安全 = 编号承诺 + 多数派相交；活 = 终有一个提议者独占足够久。Multi-Paxos 把独占做成领导者任期。</p><p>相交保证至多一个值；prepare 的「跟着已有值走」保证一旦有值就不能换。两句话就是安全。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Prepare 争承诺，accept 写值；多数派相交保唯一。</li><li>已接受值必须被更高编号带着走。</li><li>安全异步成立；终止靠部分同步与反活锁。</li><li>出处：Lamport, TOCS 1998；<em>Paxos Made Simple</em>, 2001。</li></ul>',7))])}const D=l(d,[["render",C]]);export{f as __pageData,D as default};
